@@ -31,8 +31,18 @@ VAR_OUTPUT
 	SendTimeout: BOOL;
 	//count of publish send sucsessfull
 	CountSend:ULINT;
+	// Tidal Metals fork: the connection ended within REJECT_WINDOW_MS of the client taking this QoS 1/2 message,
+	// REJECT_DISCONNECTS_MAX times in a row, and the message was given up (an MQTT 3.1.1 broker's only answer
+	// to a publish it refuses, for example a topic outside the client's ACL on mochi); not done. Without this the
+	// message was resent after every reconnect and the link never stayed up. A message queued behind a refused
