+	Rejected : BOOL;

 END_VAR
+VAR CONSTANT
+	REJECT_DISCONNECTS_MAX : UINT := 3;
+	REJECT_WINDOW_MS : UDINT := 3000;
+END_VAR

 VAR
 	requestToSend:BOOL;
@@ -50,6 +60,15 @@ VAR
 	SlotId:UINT;
 	noSendSuccessTimer:ton;
 	TimeoutRising:R_trig;
+	// Tidal Metals fork: rejected-message detection
+	IsHandedOff : BOOL;				// the client took this message (Publish succeeded) and has not finished it
+	HandedOffConnection : ULINT;	// the client's connect counter when it took the message
+	SentMs : UDINT;					// when the client took the message
+	ElapsedMs : UDINT;
+	IsLossSeen : BOOL;				// this block saw the link down since the client took the message ...
+	LostMs : UDINT;					// ... at this time
+	RejectCount : UINT;				// consecutive connections that ended within REJECT_WINDOW_MS of SentMs
+	IsRejectHeld : BOOL;			// given up while send was TRUE: wait for send FALSE before a new request
 END_VAR
 VAR_TEMP
 	PublishReturn:PUBLISH_RETURN;
@@ -61,7 +80,49 @@ SUPER^();
 IF NOT __ISVALIDREF(MQTT_IN_OUT) THEN RETURN; END_IF;
 GVL_MQTT.ProgNum := PROG_NUM.Publish;
 {info 'TODO check this, messeg is repeated!'}
-TriggerEdge(CLK:= send AND MQTT_IN_OUT.BROKER_CONNECTED);
+// Tidal Metals fork: Rejected stays until send is FALSE, and a rejected message is not started again by the
+// reconnect while send is still held
+IF NOT send THEN
+	IsRejectHeld := FALSE;
+	Rejected := FALSE;
+END_IF
+
+// Tidal Metals fork: the client began a new connection since it took this message (its connect counter changed;
+// unlike BROKER_CONNECTED this is not missed when the link drops and returns between two calls of this block).
+// The client reset its slots: send the message again, built anew from the inputs. A broker that refuses a QoS 1/2
+// publish from an MQTT 3.1.1 client closes the connection at once (mochi: a topic outside the client's ACL), and
+// upstream resent the message after every reconnect, so the link never stayed up. After REJECT_DISCONNECTS_MAX
+// connections in a row that ended within REJECT_WINDOW_MS of the client taking the message, give it up and
+// report Rejected. A lost link ends later than that (keep-alive) or not three times in a row. The end is when
+// this block first saw the link down (the client may rest before reconnecting), else when it saw the new attempt.
+IF IsHandedOff AND NOT MQTT_IN_OUT.BROKER_CONNECTED AND NOT IsLossSeen THEN
+	IsLossSeen := TRUE;
+	LostMs := SysTimeCore.SysTimeGetMs();
+END_IF
+IF IsHandedOff AND MQTT_IN_OUT.clientFB.counts.CountConnectAttempt <> HandedOffConnection
+	AND NOT MyOutData.PaketData.SendSucsess THEN
+	IsHandedOff := FALSE;
+	WasSendet := FALSE;
+	dataBuild := FALSE;
+	IF NOT IsLossSeen THEN
+		LostMs := SysTimeCore.SysTimeGetMs();
+	END_IF
+	ElapsedMs := LostMs - SentMs;	// UDINT: wraps with the clock
+	IF MyOutData.PaketData.MessageQoS <> QoS.AtMostOnce AND ElapsedMs < REJECT_WINDOW_MS THEN
+		RejectCount := RejectCount + 1;
+	ELSE
+		RejectCount := 0;
+	END_IF
+	IF RejectCount >= REJECT_DISCONNECTS_MAX THEN
+		requestToSend := FALSE;
+		Rejected := TRUE;
+		IsRejectHeld := send;
+		RejectCount := 0;
+		MQTT_IN_OUT.clientFB.PushError(newError:= ERRORS.PUBLISH_REJECTED_BY_BROKER, text:=Topic^, DoesDisconnect:= FALSE);
+	END_IF
+END_IF
+// after the check above, so a reconnect edge in the call that gives the message up does not restart it
+TriggerEdge(CLK:= send AND MQTT_IN_OUT.BROKER_CONNECTED AND NOT IsRejectHeld);

 IF NOT MQTT_IN_OUT.BROKER_CONNECTED THEN
 	//no connection, reset
